package main

// toolchain.go is a verbatim copy of src/internal/detect/toolchain.go
// (canonical implementation — ADR-004), carried locally per the repo's
// no-shared-module rule (schema.go precedent; see CLAUDE.md). The Language
// type and constants are inlined from src/internal/detect/detect.go.
//
// Generated by scripts/sync-toolchain.py — run `make sync-toolchain` after
// editing the canonical file. Do not edit this copy directly: an edit here is
// invisible to the canonical implementation and to the other copy, and
// check-surface regenerates this file to prove it did not happen.

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"strings"
	"unicode"
)

// Language mirrors src/internal/detect.Language.
type Language string

const (
	Go     Language = "go"
	Node   Language = "node"
	Python Language = "python"
	Dotnet Language = "dotnet"
)

// Pinned default toolchain images per language (ADR-004 level 3).
// These are the containers a consumer's build/test command runs in when
// nothing more specific is supplied or detected.
var defaultToolchain = map[Language]string{
	Go:     "golang:1.26-alpine",
	Node:   "node:22-alpine",
	Python: "python:3.12-slim",
	Dotnet: "mcr.microsoft.com/dotnet/sdk:8.0",
}

// Resolution bases reported in ToolchainResolution.From. They name the ADR-004
// level that produced the image, so a reader can tell a detected tag from a
// pinned default without re-deriving the precedence.
const (
	ToolchainFromExplicit = "explicit"
	ToolchainFromNvmrc    = "nvmrc"
	// ToolchainFromGlobalJSON is a global.json sdk.version that decided the image.
	ToolchainFromGlobalJSON = "global-json"
	// ToolchainFromTargetFramework is a literal <TargetFramework> in the project
	// files that decided it. ResolveToolchainDetail never returns it: reading it
	// needs a sweep of the tree rather than one root file, so only a caller that
	// can run that sweep produces it (quality's dotnetTestToolchain). It is named
	// here because the resolution levels are one vocabulary, and a level spelled
	// in the module that happens to use it is a level the other copies cannot
	// report consistently.
	ToolchainFromTargetFramework = "target-framework"
	ToolchainFromDefault         = "default"
)

// ToolchainResolution records which image a consumer command runs in and how
// that image was chosen.
//
// From is always set. Note is set only when something cicd read **was present
// and did not determine Image**, which is the state this type exists to expose:
// before it, a .nvmrc cicd read and rejected returned the same bare string as
// a repository that pinned no version at all, so the two were
// indistinguishable in the evidence and everywhere else.
//
// The trigger is deliberately "present but not decisive" rather than "declared
// but unparseable". A global.json carrying only a Microsoft.Testing.Platform
// runner opt-in declares no sdk.version at all, so an unparseable-only rule
// stays silent on it — and that file resolving to the pinned 8.0 band, which
// predates the opt-in and cannot honour it, is a real measured failure. Both
// states are a version file that exists and did not pick the image, so both
// carry a Note.
//
// An absent file carries none. Silence has to keep meaning something, and the
// thing it means here is that the repository pinned no version for this
// language.
//
// A caller that resolves from more than a root version file adds one more member
// to "present and not decisive": a version the repository did ask for that cicd
// pins no image of, so the image it runs is not the one requested. A request
// served exactly carries no Note, for the same reason an absent file does not.
type ToolchainResolution struct {
	// Image is the container image to run the consumer command in.
	Image string
	// From is one of the ToolchainFrom* constants.
	From string
	// Note is empty unless a present version file failed to determine Image.
	// It names the file, what it said, and the image used instead. It is the
	// only field a caller should turn into a warning — warning on anything
	// else produces a line on every run, which a reader learns to skip.
	Note string
}

// ResolveToolchain returns the container image to run a consumer command in,
// applying the ADR-004 precedence:
//
//  1. explicitImage — consumer-supplied, returned verbatim (the only
//     digest-pinnable level).
//  2. Version-file detection — .nvmrc → node:<major>-alpine,
//     global.json sdk.version → mcr.microsoft.com/dotnet/sdk:<major.minor>.
//  3. Pinned per-language default.
//
// Resolution never errors. Callers that need to know whether a version file was
// read and discarded must use ResolveToolchainDetail — this function cannot
// express it, which is the defect that made the detail type necessary.
func ResolveToolchain(lang, explicitImage string, src fs.FS) string {
	return ResolveToolchainDetail(lang, explicitImage, src).Image
}

// ResolveToolchainDetail is ResolveToolchain plus the provenance of its answer.
//
// Languages without a version-file convention (go, python) always resolve to
// their pinned default unless an explicit image is given, and never carry a
// Note: there is no file for them to have ignored.
func ResolveToolchainDetail(lang, explicitImage string, src fs.FS) ToolchainResolution {
	if explicitImage != "" {
		return ToolchainResolution{Image: explicitImage, From: ToolchainFromExplicit}
	}

	language := Language(strings.ToLower(lang))

	var (
		found    versionFileRead
		from     string
		filename string
		imageFor func(string) string
	)
	switch language {
	case Node:
		found, from, filename = nvmrcMajor(src), ToolchainFromNvmrc, ".nvmrc"
		imageFor = func(v string) string { return "node:" + v + "-alpine" }
	case Dotnet:
		found, from, filename = globalJSONSdkVersion(src), ToolchainFromGlobalJSON, "global.json"
		imageFor = func(v string) string { return "mcr.microsoft.com/dotnet/sdk:" + v }
	}

	if found.Value != "" {
		return ToolchainResolution{Image: imageFor(found.Value), From: from}
	}

	res := ToolchainResolution{Image: defaultToolchain[language], From: ToolchainFromDefault}
	if found.Present {
		res.Note = fmt.Sprintf("%s %s, so the pinned default %s was used instead",
			filename, found.Why, res.Image)
	}
	return res
}

// versionFileRead is what one version-file reader found. The three states it
// distinguishes are the point:
//
//	Present=false            — no such file
//	Present=true, Value==""  — a file cicd read and could not use; Why says how
//	Present=true, Value!=""  — a usable version
//
// The middle state is the one that did not exist before. Both readers used to
// return a bare (string, bool) that collapsed it into the first.
type versionFileRead struct {
	Present bool
	Value   string
	Why     string
}

// nvmrcMajor reads a .nvmrc at the filesystem root and returns the major
// version. Tolerates surrounding whitespace, a leading "v", and partial
// versions like "22".
//
// An nvm alias — lts/iron, lts/*, node, stable — is idiomatic nvm and not a
// mistake, and none of them is a version cicd can turn into a tag. Those come
// back Present with Why set, not absent.
func nvmrcMajor(src fs.FS) versionFileRead {
	raw, err := fs.ReadFile(src, ".nvmrc")
	if err != nil {
		return versionFileRead{}
	}
	trimmed := strings.TrimSpace(string(raw))
	version := strings.TrimPrefix(trimmed, "v")
	major, _, _ := strings.Cut(version, ".")
	if !isDigits(major) {
		if trimmed == "" {
			return versionFileRead{Present: true, Why: "is empty"}
		}
		return versionFileRead{Present: true, Why: fmt.Sprintf(
			"declares %s, which is not a version number", quoteFileValue(trimmed))}
	}
	return versionFileRead{Present: true, Value: major}
}

// globalJSONSdkVersion reads a global.json at the filesystem root and returns
// the major.minor of its sdk.version field.
//
// Four present-but-unusable states are distinguished in Why rather than
// collapsed, because they have different remedies: a runner-only file needs an
// sdk key added, and a bare major needs a minor.
//
// The major.minor requirement is not symmetric with .nvmrc's tolerance of a
// bare major, and that asymmetry is the trap for a careful reader rather than a
// careless one. It is kept because a bare major is not valid input to the SDK
// either, so accepting it would resolve a band from a file dotnet itself
// rejects.
func globalJSONSdkVersion(src fs.FS) versionFileRead {
	raw, err := fs.ReadFile(src, "global.json")
	if err != nil {
		return versionFileRead{}
	}
	var doc struct {
		Sdk struct {
			Version string `json:"version"`
		} `json:"sdk"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		return versionFileRead{Present: true, Why: "is not valid JSON"}
	}
	version := strings.TrimSpace(doc.Sdk.Version)
	if version == "" {
		return versionFileRead{Present: true, Why: "declares no sdk.version"}
	}
	parts := strings.Split(version, ".")
	if len(parts) < 2 || !isDigits(parts[0]) || !isDigits(parts[1]) {
		return versionFileRead{Present: true, Why: fmt.Sprintf(
			"declares sdk.version %s, which is not a major.minor version",
			quoteFileValue(version))}
	}
	return versionFileRead{Present: true, Value: parts[0] + "." + parts[1]}
}

// quoteFileValue renders a value read off the consumer's tree for inclusion in
// a message a reviewer reads.
//
// It is bounded and sanitised because the content is arbitrary: a .nvmrc is
// whatever bytes the repository committed, and this string ends up in an
// evidence envelope and in a pull-request comment. notify fences every warning
// in a code span whose delimiter the content cannot close, so this is the
// second layer rather than the only one — but a multi-megabyte .nvmrc or one
// holding control characters should not reach the renderer at all.
//
// Truncation is marked. A silently shortened value is a value the reader
// believes they are seeing in full, which is the same class of quiet mutation
// this repository refuses one layer down when it declines to strip a backtick
// out of a path.
func quoteFileValue(v string) string {
	const max = 60
	cleaned := strings.Map(func(r rune) rune {
		if r == '\n' || r == '\r' || r == '\t' {
			return ' '
		}
		if unicode.IsControl(r) {
			return -1
		}
		return r
	}, v)
	cleaned = strings.TrimSpace(cleaned)
	if len(cleaned) > max {
		return fmt.Sprintf("%q (truncated from %d bytes)", cleaned[:max], len(v))
	}
	return fmt.Sprintf("%q", cleaned)
}

// isDigits reports whether s is non-empty and consists only of ASCII digits.
func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}
